function setupSpreadsheet() {
    const table = document.getElementById('spreadsheetTable');
    // Select all data cells that are contenteditable
    const tds = table.querySelectorAll('tbody td[contenteditable="true"]');

    // Helper function to run recalculation across the whole sheet after any cell change
    const triggerRecalculation = () => {
        // Use setTimeout to ensure DOM updates (e.g., from an input event) have fully propagated before reading values.
        setTimeout(() => {
            // Find all cells that currently display a formula and need re-evaluation
            const formulaContainingTds = Array.from(tds).filter(td => {
                return td.textContent && td.textContent.trim().startsWith('=');
            });

            if (formulaContainingTds.length === 0) return;

            // Re-evaluate all formula cells sequentially based on current dependencies
            formulaContainingTds.forEach(td => {
                handleCellInput(td); // This function handles the evaluation and updates textContent
            });
        }, 50); 
    };


    tds.forEach(td => {
        // Attach event listeners to handle input changes and final calculations on blur
        td.addEventListener('input', function() {
            // When a dependency value changes, trigger global recalculation first.
            triggerRecalculation(); 
            // Also run local calculation immediately for better UX if the cell itself was a formula.
            handleCellInput(this);
        });
        // Using 'blur' ensures the final calculation runs after typing stops, and triggers dependency checks.
        td.addEventListener('blur', function() {
            handleCellInput(this);
            triggerRecalculation();
        });
    });

    console.log("Spreadsheet App Initialized: Ready for input.");
}
