/**
 * Sets the visual selection state on a column header and updates the control buttons.
 * @param {string} columnLetter The letter of the selected column (e.g., 'A').
 */
function handleColumnSelect(columnLetter) {
    const table = document.getElementById('spreadsheetTable');
    const headers = table.querySelector('thead tr');

    // 1. Clear previous selections
    document.querySelectorAll('.selected-column th, .selected-column td').forEach(el => {
        el.classList.remove('selected-column');
    });

    // 2. Apply new selection class to the header cell (the letter)
    const targetHeader = headers.querySelector(`[data-col="${columnLetter}"]`);
    if (targetHeader) {
        targetHeader.classList.add('selected-column');
    }

    // 3. Apply visual selection class to all corresponding data cells in the column
    const selector = `.spreadsheet-container tr:not(:first-child) td`; // Target body rows only
    const cellsToSelect = `${selector}[data-col="${columnLetter}"]`;
    document.querySelectorAll(cellsToSelect).forEach(cell => {
        cell.classList.add('selected-column');
    });

    // 4. Update controls
    const isSelected = !!columnLetter;
    document.getElementById('select-column-btn').disabled = true; // Keep disabled or manage state differently if needed
    document.getElementById('delete-col-btn').disabled = !isSelected;
    document.getElementById('clear-col-btn').disabled = !isSelected;
    document.getElementById('color-col-btn').disabled = !isSelected;

    document.getElementById('selected-column-display').textContent = `Selected Column: ${columnLetter}`;

    // Store the currently selected column globally or on a state object if necessary, 
    // but for simplicity, we rely on DOM manipulation/event handlers now.
    window._currentSelectedColumn = columnLetter; 
}
