        targetHeaderCell.remove();
    }

    // 2. Remove the corresponding data cells from all body rows
    bodyRows.forEach(row => {
        const targetDataCell = row.querySelector(`[data-col="${col}"]`);
        if (targetDataCell) {
            targetDataCell.remove();
        }
    });

    // 3. Clear selection state and recalculate dependencies if possible
    window._currentSelectedColumn = null;
    handleColumnSelect(null); // Resets controls and classes

    console.log(`Column ${col} deleted successfully.`);
    alert(`Column ${col} has been deleted.`);
}
