/**
 * Handles the selection of an entire column by clicking its header letter.
 * Updates UI state and enables/disables control buttons.
 * @param {string} columnLetter The letter corresponding to the selected column (e.g., 'A', 'B').
 */
function handleColumnSelect(columnLetter) {
    // 1. Clear previous selection styles
    document.querySelectorAll('.col-header, .selected-col-bg').forEach(el => {
        el.classList.remove('selected-col-header');
        if (el.tagName === 'TH') {
            el.style.backgroundColor = '';
        }
    });

    // 2. Select the current column header and apply visual feedback
    const headerElement = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (headerElement) {
        headerElement.classList.add('selected-col-header');
    } else {
         // Fallback if class structure changes, targeting the actual TH element
        const allHeaders = document.querySelectorAll('#spreadsheetTable th:not(:first-child)');
        allHeaders.forEach(th => {
            if (th.textContent.trim() === columnLetter) {
                th.classList.add('selected-col-header');
            }
        });
    }

    // 3. Update control panel visibility and state
    const controls = document.getElementById('columnControls');
    controls.style.display = 'block';
    document.getElementById('selectedColumnLetter').textContent = columnLetter;

    // Store the selected letter globally or in a dedicated element for later functions to use
    document.documentElement.dataset.selectedColumn = columnLetter;
}
