/**
 * Deletes all cells and the header corresponding to the currently selected column.
 */
function deleteSelectedColumn() {
    const selectedCol = document.documentElement.dataset.selectedColumn;
    if (!selectedCol) {
        alert("Please select a column first.");
        return;
    }

    if (!confirm(`Are you sure you want to delete the entire column ${selectedCol}? This action cannot be undone.`)) {
        return;
    }

    const table = document.getElementById('spreadsheetTable');
    let cellsToRemove = [];
    let rowsToKeep = []; // Store elements of TR that should remain

    // 1. Collect all data cells (TDs) in the selected column and remove them
    table.querySelectorAll(`tbody td[data-cell^="${selectedCol}"]`).forEach(td => {
        cellsToRemove.push(td);
    });

    // 2. Remove the header cell (TH)
    const headerCell = document.querySelector(`#spreadsheetTable thead th:nth-child(${getColIndex(selectedCol)})`);
    if (headerCell) {
        headerCell.remove();
    }


    // 3. Rebuild the table structure by iterating through rows and removing/rebuilding TDs
    let remainingRows = Array.from(table.querySelectorAll('tbody tr'));

    remainingRows.forEach((row, rowIndex) => {
        const cellsInRow = Array.from(row.querySelectorAll('td'));

        // Remove the TD corresponding to the selected column
        cellsInRow.filter(cell => cell.getAttribute('data-cell') && cell.getAttribute('data-cell').startsWith(selectedCol)).forEach(cell => {
            cell.remove();
        });
    });


    // 4. Reset selection state and UI
    handleColumnSelect(null); // Deselect the column

    console.log(`Column ${selectedCol} deleted successfully.`);
}
