function deleteColumn(columnLetter) {
    const table = document.getElementById('spreadsheetTable');
    // Find the column header (TH) to determine its position index
    let columnIndex = -1;
    const headers = table.querySelectorAll('thead th');
    for (let i = 0; i < headers.length; i++) {
        if (headers[i].getAttribute('data-column-letter') === columnLetter) {
            columnIndex = i + 1; // Offset by 1 because the first TH is the corner cell
            break;
        }
    }

    if (columnIndex < 1) {
        console.error(`Could not find column ${columnLetter} index.`);
        return false;
    }

    // 1. Remove TH from thead
    const headerToRemove = table.querySelector(`.column-header[data-column-letter="${columnLetter}"]`);
    if (headerToRemove) {
        headerToRemove.remove();
    } else {
         console.warn(`Header ${columnLetter} not found.`);
    }

    // 2. Remove all TD cells from thead and tbody
