function handleRowLabelClick(labelElement) {
    // Deselect previous row if one exists
    if (selectedRow) {
        selectedRow.classList.remove('selected-row');
        selectedRow = null;
        updateControlButtons(false); // Disable buttons initially
    }

    const rowLabelText = labelElement.textContent.trim();
    // Assuming the row label text matches the intended row number for simplicity in this context, 
    // though ideally we'd parse it from data attributes if available.
    if (!rowLabelText || isNaN(parseInt(rowLabelText))) {
        console.warn("Invalid row label clicked.");
        return;
    }

    // Find the actual row (<tr>) associated with this label. 
    // The row label is the first TH child of the TR.
    const parentRow = labelElement.closest('tr');
    if (!parentRow) return;

    selectedRow = parentRow;
    selectedRow.classList.add('selected-row');
    updateControlButtons(true); // Enable buttons
}
