/** Hides the column associated with the given header letter (e.g., 'A', 'B'). */
function hideSelectedColumn(columnLetter) {
    // Find all headers for this column letter in thead
    const columnHeaders = document.querySelectorAll('thead th');
    let targetHeader = null;

    for (const th of columnHeaders) {
        if (th.textContent.trim() === columnLetter) {
            targetHeader = th;
            break;
        }
    }

    if (!targetHeader) {
        alert(`No se encontró el encabezado de columna ${columnLetter}.`);
        return;
    }

    if (confirm(`¿Está seguro de que desea ocultar la Columna ${columnLetter}?`)) {
        // 1. Hide the header cell itself
        targetHeader.style.display = 'none';

        // 2. Hide all corresponding data cells in the body for this column
        const columnIndex = Array.from(document.querySelectorAll('thead th')).indexOf(targetHeader);
        if (columnIndex === -1) return; // Should not happen if header was found

        // Select all rows in tbody and hide the cell at the calculated index
        const dataCells = document.querySelectorAll('#spreadsheetTable tbody td');
        dataCells.forEach((td, index) => {
            // Assuming TD cells are structured correctly: Row 1 -> Index 0*10 to 9; Row 2 -> Index 1*10 to 19...
            // This is too complex for reliable indexing based on pure DOM traversal unless we know the column structure.

            // Safer approach: Iterate through all rows and target the specific TD index (columnIndex)
        });

        const rows = document.querySelectorAll('#spreadsheetTable tbody tr');
        rows.forEach(row => {
             // Check if the row has enough cells to contain this column index
            const tdsInRow = row.querySelectorAll('td');
            if (tdsInRow.length > columnIndex) {
                tdsInRow[columnIndex].style.display = 'none';
            }
        });

        console.log(`Column ${columnLetter} hidden successfully.`);
    }
}
