function getSheetData() {
    const table = document.getElementById('spreadsheetTable');
    const sheetData = {}; 

    // Iterate over all editable cells in the body
    const tds = table.querySelectorAll('tbody td[contenteditable="true"]');

    tds.forEach((td, index) => {
        const row = td.closest('tr');
        if (row) {
            // Calculate the specific key based on row and column position relative to the whole body
            const rowIndex = Array.from(table.querySelectorAll('tbody tr')).indexOf(row);
            const colIndex = index; 

            // Key format: R<rowIndex>C<colIndex>
            sheetData[`R${rowIndex}C${colIndex}`] = td.textContent.trim();
        }
    });
    return sheetData;
}

