    /** Deletes an entire column element from the DOM given its letter (e.g., 'B'). */
    function deleteColumn(colLetter) {
        const table = document.getElementById('spreadsheetTable');
        if (!colLetter || !/[A-Z]/.test(colLetter)) {
            alert("Por favor, ingrese una letra de columna válida.");
            return;
        }

        // 1. Determine the physical index of the column letter (e.g., A=2nd TH child, B=3rd TH child)
        const thElements = Array.from(table.querySelectorAll('thead th'));
        let columnIndexInThead = -1; 

        // Loop through data columns starting from the second TH element (index 1)
        for(let i = 1; i < thElements.length; i++) { 
            if (thElements[i].textContent.trim() === colLetter) {
                columnIndexInThead = i;
                break;
            }
        }

        if (columnIndexInThead === -1) {
            alert(`No se encontró la columna ${colLetter}.`);
            return;
        }

        const selectedHeader = thElements[columnIndexInThead];

        if (!confirm(`⚠️ ¿Está seguro de que desea eliminar permanentemente la columna ${colLetter}? Esta acción borrará todos los datos en esta columna.`)) {
            return;
        }

        // 2. Remove the header cell
        selectedHeader.remove();

        // 3. Iterate through all rows (tbody tr) and remove the corresponding TD cell
        const bodyRows = table.querySelectorAll('tbody tr');
        bodyRows.forEach(row => {
            // The physical column index is columnIndexInThead + 2: 
            // +1 for corner TH, +1 for row label TH (which is also a TH)
            const tdToRemove = row.querySelector(`td:nth-child(${columnIndexInThead + 2})`); 
             if (tdToRemove) {
                tdToRemove.remove();
            }
        });

        console.log(`Column ${colLetter} deleted successfully.`);
    }
